async function getDashboardData() {
  const [analytics, notifications, settings] = await Promise.all(
    ['/api/analytics', '/api/notifications', '/api/settings'].map(async (url) => {
      const response = await fetch(url)
      if (!response.ok) {
        throw new Error(`Failed to fetch ${url}: ${response.status}`)
      }
      return response.json()
    }),
  )

  return { analytics, notifications, settings }
}

export default async function Dashboard() {
  let data: Awaited<ReturnType<typeof getDashboardData>>

  try {
    data = await getDashboardData()
  } catch {
    return (
      <section>
        <h2>Dashboard Content</h2>
        <p>Dashboard data is unavailable.</p>
      </section>
    )
  }

  return (
    <section>
      <h2>Dashboard Content</h2>
      <h3>Analytics</h3>
      <pre>{JSON.stringify(data.analytics, null, 2)}</pre>
      <h3>Notifications</h3>
      <pre>{JSON.stringify(data.notifications, null, 2)}</pre>
      <h3>Settings</h3>
      <pre>{JSON.stringify(data.settings, null, 2)}</pre>
    </section>
  )
}

